const contactForm=document.querySelector(".contact-form-panel form");contactForm&&contactForm.addEventListener("submit",async u=>{u.preventDefault();const e=contactForm.querySelector('button[type="submit"]');if(!e)return;const d=e.textContent,s=document.getElementById("contactName"),t=document.getElementById("contactEmail"),a=document.getElementById("contactMessage");if(!s||!t||!a){alert("Required form fields are missing in the document.");return}const n=s.value.trim(),r=t.value.trim(),o=a.value.trim();if(n===""){alert("Please enter your name."),s.focus();return}if(r===""){alert("Please enter your email address."),t.focus();return}if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(r)){alert("Please enter a valid email address."),t.focus();return}if(o===""){alert("Please enter your message."),a.focus();return}const c=contactForm.querySelector('[name="h-captcha-response"]'),i=c?c.value:"";if(!i){alert("Please complete the hCaptcha verification.");return}e.textContent="Sending Message...",e.disabled=!0;const f="c844132e-cd0b-4bc0-87b9-6e009b54f720";try{const m=await(await fetch("https://api.web3forms.com/submit",{method:"POST",headers:{"Content-Type":"application/json",Accept:"application/json"},body:JSON.stringify({access_key:f,name:n,email:r,message:o,"h-captcha-response":i,subject:"New Portfolio Contact Message from "+n})})).json();m.success?(alert("Thank you! Your message has been sent successfully."),contactForm.reset(),typeof hcaptcha<"u"&&hcaptcha.reset()):alert("Something went wrong. Error: "+m.message)}catch(l){alert("Network error. Failed to send message."),console.error(l)}finally{e.textContent=d,e.disabled=!1}});
